with v(k,q) as (values ('livestock.0','livestock barn authorized'),('kitchen.0','fryer hot oil'),('kitchen.1','kitchen hood fire suppression'),('kitchen.2','slicer sharp blade'),('wet_floor.0','slippery floor washdown'),('cold_storage.0','walk in freezer door release'),('cold_storage.1','freezer cold storage ppe'),('ammonia.0','ammonia machinery room authorized'),('ammonia.1','ammonia leak emergency shutdown'),('chlorine.0','chlorine gas storage'),('chlorine.1','chemical feed room authorized'),('h2s.0','hydrogen sulfide h2s'),('lab.0','laboratory eye protection lab coat'),('lab.1','no food or drink laboratory'),('biohazard.0','biohazard area authorized'),('biohazard.1','sharps container disposal'),('radiation.0','radiation area x-ray'),('radiation.1','mri magnet always on'),('shop_class.0','shop class eye protection'),('shop_class.1','machine use instructor permission'),('pool.0','pool chemical storage'),('pool.1','no lifeguard on duty swim at own risk')),
r as (select v.k, s.sku, row_number() over (partition by v.k order by s.score desc) rn from v cross join lateral finder.search_ids(v.q,null,null,null,null,10) s)
select r.k, r.rn, c.handle, left(c.title,90) t from r join lateral finder.cards(array[r.sku]) c on true where r.rn<=3 order by r.k, r.rn